namespace YourNamespace
{
    public class CheckoutModel : PageModel
    {
        private readonly IConfiguration _configuration;
        private readonly DbDataSource _dbDataSource;

        public CheckoutModel(IConfiguration configuration, DbDataSource dbDataSource)
        {
            _configuration = configuration;
            _dbDataSource = dbDataSource;
        }

        public async Task<IActionResult> OnPostAsync(CancellationToken cancellationToken)
        {
            var cart = HttpContext.Session.Get<Dictionary<int, int>>(SessionKey.Cart);
            if (cart == null || cart.Count == 0)
            {
                ModelState.AddModelError(string.Empty, "Your cart is empty.");
                return Page();
            }

            string address = ShippingAddressBox.Text;
            string connectionString = _configuration.GetConnectionString("ShopDb");

            using (var connection = new SqlConnection(connectionString))
            {
                connection.Open();
                var insert = new SqlCommand(
                    "INSERT INTO Orders (CustomerId, ShippingAddress) VALUES (@CustomerId, @ShippingAddress); SELECT SCOPE_IDENTITY();",
                    connection);
                insert.Parameters.AddWithValue("@CustomerId", SessionKey.CustomerId);
                insert.Parameters.AddWithValue("@ShippingAddress", address);
                int orderId = Convert.ToInt32(insert.ExecuteScalar());

                foreach (var item in cart)
                {
                    var update = new SqlCommand(
                        "UPDATE Inventory SET Stock = Stock - @Quantity WHERE ProductId = @ProductId",
                        connection);
                    update.Parameters.AddWithValue("@ProductId", item.Key);
                    update.Parameters.AddWithValue("@Quantity", item.Value);
                    update.ExecuteNonQuery();
                }

                Session.Remove(SessionKey.Cart);
                return RedirectToPage("Confirmation", new { orderId = orderId });
            }
        }

        private static class SessionKey
        {
            public const string Cart = "Cart";
            public const string CustomerId = "CustomerId";
        }
    }
}

