namespace ClassicAspToCore
{
    public class DeleteCommentModel : PageModel
    {
        private readonly IConfiguration _configuration;

        public DeleteCommentModel(IConfiguration configuration)
        {
            _configuration = configuration;
        }

        public async Task<IActionResult> OnGetAsync(string commentId, string postId, CancellationToken cancellationToken)
        {
            if (string.IsNullOrEmpty(commentId) || string.IsNullOrEmpty(postId))
            {
                return BadRequest();
            }

            if (string.IsNullOrEmpty(User.Identity.Name))
            {
                return Redirect("/Account/Login");
            }

            string connectionString = _configuration.GetConnectionString("DefaultConnection");

            using (DbDataSource dataSource = new DbDataSource(connectionString))
            {
                using (DbCommand command = dataSource.CreateCommand())
                {
                    command.CommandText = "DELETE FROM Comments WHERE CommentId = @CommentId AND AuthorId = @AuthorId";
                    command.Parameters.AddWithValue("@CommentId", commentId);
                    command.Parameters.AddWithValue("@AuthorId", User.Identity.Name);
                    await command.ExecuteNonQueryAsync(cancellationToken);
                }
            }

            return Redirect($"/Posts/Details?id={postId}");
        }
    }
}

