namespace ClassicAspToCore.Pages
{
    public class ProductSearchModel : PageModel
    {
        private readonly IConfiguration _configuration;

        public ProductSearchModel(IConfiguration configuration)
        {
            _configuration = configuration;
        }

        public string Keyword { get; set; }
        public List<Product> Products { get; set; }

        public async Task OnGetAsync(CancellationToken cancellationToken)
        {
            Keyword = HttpContext.Request.Form["keyword"] ?? HttpContext.Request.Cookies["lastSearch"];
            HttpContext.Response.Cookies.Append("lastSearch", Keyword, new CookieOptions { Expires = DateTime.Now.AddDays(30) });

            using (var connection = new DbDataSource(_configuration.GetConnectionString("ShopDb")))
            {
                var sql = "SELECT Name, Price FROM Products WHERE Name LIKE @Keyword ORDER BY Name";
                var parameters = new { Keyword = $"%{Keyword}%" };
                Products = await connection.QueryAsync<Product>(sql, parameters, cancellationToken);
            }
        }
    }

    public record Product(string Name, decimal Price);
}

