using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.RazorPages;
using Microsoft.Extensions.Configuration;
using System.Collections.Generic;
using System.Data.Common;
using System.Globalization;
using System.Threading;
using System.Threading.Tasks;

namespace ClassicAspToCore.Pages
{
    public class OrderDetailsModel : PageModel
    {
        private readonly IConfiguration _configuration;

        public OrderDetailsModel(IConfiguration configuration)
        {
            _configuration = configuration;
        }

        public string OrderId { get; set; }
        public List<OrderLine> OrderLines { get; set; }

        public async Task<IActionResult> OnGetAsync(string orderId, CancellationToken cancellationToken)
        {
            OrderId = orderId;
            OrderLines = await GetOrderLinesAsync(orderId, cancellationToken);
            return Page();
        }

        private async Task<List<OrderLine>> GetOrderLinesAsync(string orderId, CancellationToken cancellationToken)
        {
            using (var connection = DbDataSource.CreateConnection(_configuration.GetConnectionString("DefaultConnection")))
            {
                await connection.OpenAsync(cancellationToken);

                using (var command = connection.CreateCommand())
                {
                    command.CommandText = "SELECT ProductName, Quantity, Status FROM OrderLines WHERE OrderId = @OrderId";
                    command.Parameters.AddWithValue("@OrderId", orderId);

                    using (var reader = await command.ExecuteReaderAsync(cancellationToken))
                    {
                        var orderLines = new List<OrderLine>();
                        while (await reader.ReadAsync(cancellationToken))
                        {
                            orderLines.Add(new OrderLine
                            {
                                ProductName = reader.GetString(0),
                                Quantity = reader.GetInt32(1),
                                Status = reader.GetString(2)
                            });
                        }
                        return orderLines;
                    }
                }
            }
        }
    }

    public class OrderLine
    {
        public string ProductName { get; set; }
        public int Quantity { get; set; }
        public string Status { get; set; }
    }
}

